1	/**
2	 * The `@Effect()` decorator migration for `@ngrx/effects`.
3	 *
4	 * NgRx deprecated the `@Effect()` property decorator in version 11 and removed
5	 * the export in version 15, in favour of the `createEffect()` factory. A
6	 * workspace lifted across that boundary does not merely warn: the import fails
7	 * to resolve and the build stops, so a decorated effect is a hard blocker for
8	 * any Angular line whose NgRx peer is 15 or newer.
9	 *
10	 * The rewrite is defined by NgRx, not by any application:
11	 *
12	 * ```ts
13	 * ⁠@Effect()                        name$ = createEffect(() => SOURCE);
14	 * name$ = SOURCE;              ->
15	 *
16	 * ⁠@Effect({ dispatch: false })      name$ = createEffect(() => SOURCE, { dispatch: false });
17	 * name$ = SOURCE;              ->
18	 * ```
19	 *
20	 * The decorator's configuration object, when it has one, is carried through
21	 * verbatim as `createEffect`'s second argument — the two take the same shape,
22	 * so no option is reinterpreted here.
23	 *
24	 * Everything rides the parsed module. The decorator is located by resolving the
25	 * local binding that `@ngrx/effects` exported as `Effect`, so a module that
26	 * imports some other `Effect` is untouched, and a module that aliases NgRx's
27	 * (`import { Effect as NgRxEffect }`) is still rewritten. A property this
28	 * capability cannot rewrite safely is left exactly as it is and reported; it is
29	 * never partially edited, because a half-rewritten effect would compile into
30	 * silently dead behaviour rather than failing loudly.
31	 */
32	
33	import { analyze } from 'yuku-analyzer';
34	import { compareStrings } from './angular-target-cell.ts';
35	
36	/** The module whose `Effect` export this capability replaces. */
37	export const NGRX_EFFECTS_MODULE = '@ngrx/effects';
38	
39	/** The removed decorator, and the factory that replaced it. */
40	export const REMOVED_EFFECT_DECORATOR = 'Effect';
41	export const EFFECT_FACTORY = 'createEffect';
42	
43	export type NgrxEffectChange = Readonly<{
44		kind: 'ngrx-effect-decorator';
45		line: number;
46		from: string;
47		to: string;
48	}>;
49	
50	export type NgrxEffectsMigration = Readonly<{
51		path: string;
52		source: string;
53		changed: boolean;
54		changes: readonly NgrxEffectChange[];
55		unhandled: readonly string[];
56	}>;
57	
58	type Span = readonly [number, number];
59	
60	type Edit = Readonly<{ start: number; end: number; text: string }>;
61	
62	function spanOf(node: unknown): Span | null {
63		if (typeof node !== 'object' || node === null) return null;
64		const candidate = node as { start?: unknown; end?: unknown; range?: unknown };
65		if (typeof candidate.start === 'number' && typeof candidate.end === 'number')
66			return [candidate.start, candidate.end];
67		const range = candidate.range;
68		if (!Array.isArray(range) || range.length < 2) return null;
69		const [start, end] = range as readonly unknown[];
70		return typeof start === 'number' && typeof end === 'number' ? [start, end] : null;
71	}
72	
73	function objectNode(value: unknown): Readonly<Record<string, unknown>> | null {
74		return typeof value === 'object' && value !== null && !Array.isArray(value)
75			? (value as Readonly<Record<string, unknown>>)
76			: null;
77	}
78	
79	function nodeType(value: unknown): string | null {
80		const node = objectNode(value);
81		const type = node?.['type'];
82		return typeof type === 'string' ? type : null;
83	}
84	
85	function identifierName(value: unknown): string | null {
86		const node = objectNode(value);
87		if (node === null || node['type'] !== 'Identifier') return null;
88		const name = node['name'];
89		return typeof name === 'string' ? name : null;
90	}
91	
92	function lineOf(source: string, offset: number): number {
93		return source.slice(0, offset).split('\n').length;
94	}
95	
96	/**
97	 * The import declaration's bindings for the module, as a map from the exported
98	 * name to the local binding name. A namespace or default import contributes
99	 * nothing here and is reported by the caller, because a rewrite through one
100	 * would have to guess at member access.
101	 */
102	type ModuleBindings = Readonly<{
103		/** Exported name -> local name, for named imports only. */
104		named: ReadonlyMap<string, string>;
105		/** Local names bound by a namespace or default import. */
106		wide: readonly string[];
107	}>;
108	
109	function readModuleBindings(body: readonly unknown[], module: string): ModuleBindings {
110		const named = new Map<string, string>();
111		const wide: string[] = [];
112		for (const statement of body) {
113			if (nodeType(statement) !== 'ImportDeclaration') continue;
114			const node = objectNode(statement);
115			const source = objectNode(node?.['source']);
116			if (source?.['value'] !== module) continue;
117			const specifiers = node?.['specifiers'];
118			if (!Array.isArray(specifiers)) continue;
119			for (const specifier of specifiers as readonly unknown[]) {
120				const type = nodeType(specifier);
121				const entry = objectNode(specifier);
122				if (entry === null) continue;
123				const local = identifierName(entry['local']);
124				if (local === null) continue;
125				if (type !== 'ImportSpecifier') {
126					wide.push(local);
127					continue;
128				}
129				const imported = identifierName(entry['imported']) ?? local;
130				named.set(imported, local);
131			}
132		}
133		return Object.freeze({ named, wide: Object.freeze(wide) });
134	}
135	
136	/** Every identifier name bound at the top level of the module. */
137	function topLevelBindings(body: readonly unknown[]): ReadonlySet<string> {
138		const names = new Set<string>();
139		const collect = (pattern: unknown): void => {
140			const name = identifierName(pattern);
141			if (name !== null) names.add(name);
142		};
143		for (const statement of body) {
144			const node = objectNode(statement);
145			if (node === null) continue;
146			const declaration =
147				node['type'] === 'ExportNamedDeclaration' || node['type'] === 'ExportDefaultDeclaration'
148					? objectNode(node['declaration'])
149					: node;
150			if (declaration === null) continue;
151			if (declaration['type'] === 'ImportDeclaration') {
152				for (const specifier of (declaration['specifiers'] as readonly unknown[]) ?? [])
153					collect(objectNode(specifier)?.['local']);
154				continue;
155			}
156			if (declaration['type'] === 'VariableDeclaration') {
157				for (const entry of (declaration['declarations'] as readonly unknown[]) ?? [])
158					collect(objectNode(entry)?.['id']);
159				continue;
160			}
161			collect(declaration['id']);
162		}
163		return names;
164	}
165	
166	type DecoratedProperty = Readonly<{
167		decoratorSpan: Span;
168		keyStart: number;
169		valueSpan: Span;
170		optionsSpan: Span | null;
171		name: string;
172	}>;
173	
174	/**
175	 * Find every class property decorated with `local`, walking every class in the
176	 * module — declared, exported, or assigned to a variable.
177	 */
178	function decoratedProperties(
179		body: readonly unknown[],
180		local: string,
181		unhandled: string[],
182		path: string,
183	): DecoratedProperty[] {
184		const found: DecoratedProperty[] = [];
185		const visit = (value: unknown): void => {
186			const node = objectNode(value);
187			if (node === null) return;
188			if (node['type'] === 'ClassDeclaration' || node['type'] === 'ClassExpression') {
189				const classBody = objectNode(node['body']);
190				for (const member of (classBody?.['body'] as readonly unknown[]) ?? [])
191					readMember(member);
192				return;
193			}
194			for (const child of Object.values(node)) {
195				if (Array.isArray(child)) for (const item of child) visit(item);
196				else if (typeof child === 'object' && child !== null) visit(child);
197			}
198		};
199		const readMember = (member: unknown): void => {
200			const node = objectNode(member);
201			if (node === null || node['type'] !== 'PropertyDefinition') return;
202			const decorators = (node['decorators'] as readonly unknown[]) ?? [];
203			for (const decorator of decorators) {
204				const expression = objectNode(objectNode(decorator)?.['expression']);
205				if (expression === null) continue;
206				const isCall = expression['type'] === 'CallExpression';
207				const callee = isCall ? expression['callee'] : expression;
208				if (identifierName(callee) !== local) continue;
209				const name = identifierName(node['key']) ?? '(computed)';
210				const decoratorSpan = spanOf(decorator);
211				const keySpan = spanOf(node['key']);
212				const valueSpan = spanOf(node['value']);
213				if (decoratorSpan === null || keySpan === null || valueSpan === null) {
214					unhandled.push(
215						`${path}: the property decorated with ${local} could not be located precisely ` +
216							'in the source and was left decorated',
217					);
218					continue;
219				}
220				const args = isCall ? ((expression['arguments'] as readonly unknown[]) ?? []) : [];
221				if (args.length > 1) {
222					unhandled.push(
223						`${path}: ${name} is decorated with more than one ${local} argument, which ` +
224							`${EFFECT_FACTORY} does not take; it was left decorated`,
225					);
226					continue;
227				}
228				const optionsSpan = args.length === 1 ? spanOf(args[0]) : null;
229				if (args.length === 1 && optionsSpan === null) {
230					unhandled.push(
231						`${path}: ${name}'s ${local} argument could not be located in the source; it ` +
232							'was left decorated',
233					);
234					continue;
235				}
236				found.push({
237					decoratorSpan,
238					keyStart: keySpan[0],
239					valueSpan,
240					optionsSpan,
241					name,
242				});
243			}
244		};
245		for (const statement of body) visit(statement);
246		return found;
247	}
248	
249	/**
250	 * Replace `@Effect()`-decorated properties in one module with
251	 * `createEffect(...)` initialisers, and rewrite the import to match.
252	 *
253	 * A module that imports nothing from `@ngrx/effects`, or imports it without the
254	 * removed decorator, is returned byte-identical. A module that does not parse
255	 * is a hard failure naming the file, never a silent skip.
256	 */
257	export function migrateNgrxEffectDecorators(path: string, source: string): NgrxEffectsMigration {
258		const unchanged = (unhandled: readonly string[] = []): NgrxEffectsMigration =>
259			Object.freeze({
260				path,
261				source,
262				changed: false,
263				changes: Object.freeze([]),
264				unhandled: Object.freeze([...new Set(unhandled)].sort(compareStrings)),
265			});
266		if (!source.includes(NGRX_EFFECTS_MODULE)) return unchanged();
267		const analyzed = analyze(source, { path, lang: path.endsWith('.ts') ? 'ts' : 'js' });
268		const errors = analyzed.diagnostics.filter((entry) => entry.severity === 'error');
269		if (errors.length > 0)
270			throw new Error(
271				`NgRx effects migration: ${path} does not parse, so its removed ${REMOVED_EFFECT_DECORATOR} ` +
272					'decorators cannot be rewritten and it cannot be honestly counted as unchanged. ' +
273					`Diagnostics: ${errors.map((entry) => entry.message).join('; ')}`,
274			);
275		const body = analyzed.ast.body as readonly unknown[];
276		const bindings = readModuleBindings(body, NGRX_EFFECTS_MODULE);
277		const unhandled: string[] = [];
278		if (bindings.wide.length > 0)
279			unhandled.push(
280				`${path} imports ${NGRX_EFFECTS_MODULE} as a namespace or default binding; a ` +
281					`${REMOVED_EFFECT_DECORATOR} reached through one is not rewritten`,
282			);
283		const local = bindings.named.get(REMOVED_EFFECT_DECORATOR);
284		if (local === undefined) return unchanged(unhandled);
285		const properties = decoratedProperties(body, local, unhandled, path);
286		if (properties.length === 0) return unchanged(unhandled);
287		const factoryLocal = bindings.named.get(EFFECT_FACTORY);
288		const declared = topLevelBindings(body);
289		if (factoryLocal === undefined && declared.has(EFFECT_FACTORY)) {
290			unhandled.push(
291				`${path} already binds the name ${EFFECT_FACTORY} to something other than ` +
292					`${NGRX_EFFECTS_MODULE}'s factory, so its ${REMOVED_EFFECT_DECORATOR} decorators ` +
293					'were left in place rather than shadowed',
294			);
295			return unchanged(unhandled);
296		}
297		const factory = factoryLocal ?? EFFECT_FACTORY;
298		const edits: Edit[] = [];
299		const changes: NgrxEffectChange[] = [];
300		for (const property of properties) {
301			const options =
302				property.optionsSpan === null
303					? ''
304					: `, ${source.slice(property.optionsSpan[0], property.optionsSpan[1])}`;
305			edits.push({ start: property.decoratorSpan[0], end: property.keyStart, text: '' });
306			edits.push({
307				start: property.valueSpan[0],
308				end: property.valueSpan[0],
309				text: `${factory}(() => `,
310			});
311			edits.push({ start: property.valueSpan[1], end: property.valueSpan[1], text: `${options})` });
312			const decorator = source.slice(property.decoratorSpan[0], property.decoratorSpan[1]);
313			changes.push({
314				kind: 'ngrx-effect-decorator',
315				line: lineOf(source, property.decoratorSpan[0]),
316				from: `${decorator} ${property.name}`,
317				to: `${property.name} = ${factory}(() => …${options})`,
318			});
319		}
320		/**
321		 * Rewrite the named-specifier list as a whole rather than surgically
322		 * deleting one entry and appending another. Editing the entries in place has
323		 * to reason about which comma belongs to which neighbour, and the case where
324		 * the removed decorator is the list's only entry produces a dangling comma
325		 * that does not parse. Replacing the span from the first named specifier to
326		 * the last is exact in every arrangement, including a default import
327		 * standing outside the braces, whose span is deliberately left alone.
328		 */
329		const namedSpecifiers: { span: Span; text: string; local: string | null }[] = [];
330		for (const statement of body) {
331			if (nodeType(statement) !== 'ImportDeclaration') continue;
332			const node = objectNode(statement);
333			if (objectNode(node?.['source'])?.['value'] !== NGRX_EFFECTS_MODULE) continue;
334			for (const specifier of (node?.['specifiers'] as readonly unknown[]) ?? []) {
335				if (nodeType(specifier) !== 'ImportSpecifier') continue;
336				const span = spanOf(specifier);
337				if (span === null) continue;
338				namedSpecifiers.push({
339					span,
340					text: source.slice(span[0], span[1]),
341					local: identifierName(objectNode(specifier)?.['local']),
342				});
343			}
344		}
345		if (namedSpecifiers.length === 0) {
346			unhandled.push(
347				`${path} imports ${REMOVED_EFFECT_DECORATOR} in a form this capability cannot rewrite ` +
348					`into ${EFFECT_FACTORY}; its decorators were left in place`,
349			);
350			return unchanged(unhandled);
351		}
352		const kept = namedSpecifiers.filter((entry) => entry.local !== local).map((entry) => entry.text);
353		if (factoryLocal === undefined) kept.push(EFFECT_FACTORY);
354		const first = namedSpecifiers[0] as (typeof namedSpecifiers)[number];
355		const last = namedSpecifiers[namedSpecifiers.length - 1] as (typeof namedSpecifiers)[number];
356		edits.push({ start: first.span[0], end: last.span[1], text: kept.join(', ') });
357		const ordered = [...edits].sort((left, right) => right.start - left.start || right.end - left.end);
358		let migrated = source;
359		for (const edit of ordered)
360			migrated = `${migrated.slice(0, edit.start)}${edit.text}${migrated.slice(edit.end)}`;
361		return Object.freeze({
362			path,
363			source: migrated,
364			changed: migrated !== source,
365			changes: Object.freeze(changes),
366			unhandled: Object.freeze([...new Set(unhandled)].sort(compareStrings)),
367		});
368	}
