1	/**
2	 * Application source migration for an Angular CLI era workspace.
3	 *
4	 * Two shapes are handled, both of them defined by Angular and its runtime
5	 * dependencies rather than by any application:
6	 *
7	 * - Deep `zone.js/dist/*` specifiers. zone.js 0.11 replaced the `dist`
8	 *   directory layout the Angular CLI's generated `polyfills.ts` and `test.ts`
9	 *   import from with package entry points, so a workspace generated before it
10	 *   names files that no longer exist on a modern line and fails to resolve.
11	 * - Testing symbols `@angular/core/testing` renamed and then removed, of which
12	 *   `async` — renamed to `waitForAsync` because it collided with the
13	 *   ECMAScript keyword — is the one this table carries.
14	 *
15	 * Every rewrite rides the parsed module rather than the text: only the source
16	 * literal of an `import`/`export … from` declaration is edited, so a matching
17	 * string inside a comment, a template, or an ordinary expression is left
18	 * exactly where it is. A commented-out `import 'zone.js/dist/zone-error'` — a
19	 * line the Angular CLI itself generates into `src/environments/environment.ts`
20	 * — is therefore not touched, which a textual substitution would get wrong.
21	 */
22	
23	import { analyze } from 'yuku-analyzer';
24	import { compareStrings } from './angular-target-cell.ts';
25	
26	/**
27	 * zone.js's package entry points, keyed by the `dist` path they replaced. The
28	 * bundle files under `dist` were the public surface before 0.11; afterwards the
29	 * same code is reachable only through these specifiers.
30	 */
31	export const ZONE_JS_SPECIFIER_REPLACEMENTS: Readonly<Record<string, string>> = Object.freeze({
32		'zone.js/dist/long-stack-trace-zone': 'zone.js/plugins/long-stack-trace-zone',
33		'zone.js/dist/task-tracking': 'zone.js/plugins/task-tracking',
34		'zone.js/dist/webapis-media-query': 'zone.js/plugins/webapis-media-query',
35		'zone.js/dist/zone': 'zone.js',
36		'zone.js/dist/zone-error': 'zone.js/plugins/zone-error',
37		'zone.js/dist/zone-patch-rxjs': 'zone.js/plugins/zone-patch-rxjs',
38		'zone.js/dist/zone-testing': 'zone.js/testing',
39	});
40	
41	/**
42	 * Renamed exports, keyed by module specifier and then by the removed export
43	 * name. The rewrite keeps the local binding name the module already uses
44	 * (`import { waitForAsync as async }`), so no call site changes and no scope
45	 * analysis is required to be correct. It does not modernise call-site naming:
46	 * a module that used `async(...)` still reads `async(...)` afterwards, and this
47	 * capability claims nothing more than that the removed export is no longer
48	 * requested.
49	 */
50	export const RENAMED_MODULE_EXPORTS: Readonly<Record<string, Readonly<Record<string, string>>>> =
51		Object.freeze({
52			'@angular/core/testing': Object.freeze({ async: 'waitForAsync' }),
53		});
54	
55	export type SourceChange = Readonly<{
56		kind: 'module-specifier' | 'renamed-export';
57		line: number;
58		from: string;
59		to: string;
60	}>;
61	
62	export type SourceMigration = Readonly<{
63		path: string;
64		source: string;
65		changed: boolean;
66		changes: readonly SourceChange[];
67		unhandled: readonly string[];
68	}>;
69	
70	type Edit = Readonly<{ start: number; end: number; text: string; change: SourceChange }>;
71	
72	type SourceSpan = readonly [number, number];
73	
74	type SourceLiteral = Readonly<{ value: string; span: SourceSpan }>;
75	
76	type ImportSpecifierNode = Readonly<{
77		type: string;
78		imported?: Readonly<{ type: string; name?: string }>;
79		local?: Readonly<{ name: string }>;
80	}>;
81	
82	/**
83	 * The half-open source span of a node. The parser reports `start`/`end`; the
84	 * ESTree `range` pair is accepted as well so the capability does not depend on
85	 * which of the two spellings a parser build emits.
86	 */
87	function spanOf(node: unknown): SourceSpan | null {
88		if (typeof node !== 'object' || node === null) return null;
89		const candidate = node as { start?: unknown; end?: unknown; range?: unknown };
90		if (typeof candidate.start === 'number' && typeof candidate.end === 'number')
91			return [candidate.start, candidate.end];
92		const range = candidate.range;
93		if (!Array.isArray(range) || range.length < 2) return null;
94		const [start, end] = range as readonly unknown[];
95		return typeof start === 'number' && typeof end === 'number' ? [start, end] : null;
96	}
97	
98	type DeclarationNode = Readonly<{
99		type: string;
100		source?: unknown;
101		specifiers?: readonly unknown[];
102		importKind?: string;
103	}>;
104	
105	function sourceLiteral(node: unknown): SourceLiteral | null {
106		if (typeof node !== 'object' || node === null) return null;
107		const candidate = node as { value?: unknown };
108		if (typeof candidate.value !== 'string') return null;
109		const span = spanOf(node);
110		return span === null ? null : { value: candidate.value, span };
111	}
112	
113	function importSpecifier(node: unknown): ImportSpecifierNode | null {
114		if (typeof node !== 'object' || node === null) return null;
115		const candidate = node as ImportSpecifierNode;
116		return typeof candidate.type === 'string' ? candidate : null;
117	}
118	
119	/**
120	 * Requote a replacement specifier the way the original literal was written, so
121	 * a rewritten import keeps the file's quote style and the diff stays confined
122	 * to the specifier itself. An unrecognised opening quote falls back to a JSON
123	 * string, which is always valid.
124	 */
125	function quoteLike(original: string, replacement: string): string {
126		const quote = original.slice(0, 1);
127		if (
128			(quote !== "'" && quote !== '"') ||
129			replacement.includes(quote) ||
130			replacement.includes('\\')
131		)
132			return JSON.stringify(replacement);
133		return `${quote}${replacement}${quote}`;
134	}
135	
136	function lineOf(source: string, offset: number): number {
137		return source.slice(0, offset).split('\n').length;
138	}
139	
140	/**
141	 * Rewrite one module's era specifiers and renamed imports. A module with
142	 * nothing to rewrite is returned byte-identical, with `changed` false.
143	 *
144	 * A module that does not parse is a hard failure naming the file and the
145	 * diagnostics, never a silent skip: a skipped file would be counted as
146	 * unchanged, and an uncounted file is exactly the defect a migration record
147	 * exists to rule out.
148	 */
149	export function migrateAngularSourceModule(path: string, source: string): SourceMigration {
150		const analyzed = analyze(source, { path, lang: path.endsWith('.ts') ? 'ts' : 'js' });
151		const errors = analyzed.diagnostics.filter((entry) => entry.severity === 'error');
152		if (errors.length > 0)
153			throw new Error(
154				`Angular source migration: ${path} does not parse, so its era shapes cannot be ` +
155					`rewritten and it cannot be honestly counted as unchanged. Diagnostics: ` +
156					errors.map((entry) => entry.message).join('; '),
157			);
158		const edits: Edit[] = [];
159		const unhandled: string[] = [];
160		for (const statement of analyzed.ast.body as readonly unknown[]) {
161			const declaration = statement as DeclarationNode;
162			if (
163				declaration.type !== 'ImportDeclaration' &&
164				declaration.type !== 'ExportNamedDeclaration' &&
165				declaration.type !== 'ExportAllDeclaration'
166			)
167				continue;
168			const literal = sourceLiteral(declaration.source);
169			if (literal === null) continue;
170			const replacement = ZONE_JS_SPECIFIER_REPLACEMENTS[literal.value];
171			if (replacement !== undefined)
172				edits.push({
173					start: literal.span[0],
174					end: literal.span[1],
175					text: quoteLike(source.slice(literal.span[0], literal.span[1]), replacement),
176					change: {
177						kind: 'module-specifier',
178						line: lineOf(source, literal.span[0]),
179						from: literal.value,
180						to: replacement,
181					},
182				});
183			const renames = RENAMED_MODULE_EXPORTS[literal.value];
184			if (renames === undefined) continue;
185			for (const node of declaration.specifiers ?? []) {
186				const specifier = importSpecifier(node);
187				if (specifier === null || specifier.type !== 'ImportSpecifier') continue;
188				const imported = specifier.imported;
189				if (imported === undefined || imported.type !== 'Identifier') continue;
190				const name = imported.name;
191				if (name === undefined) continue;
192				const renamed = renames[name];
193				if (renamed === undefined) continue;
194				const local = specifier.local?.name ?? name;
195				const span = spanOf(node);
196				if (span === null) continue;
197				edits.push({
198					start: span[0],
199					end: span[1],
200					text: `${renamed} as ${local}`,
201					change: {
202						kind: 'renamed-export',
203						line: lineOf(source, span[0]),
204						from: `${name} as ${local}`,
205						to: `${renamed} as ${local}`,
206					},
207				});
208			}
209		}
210		for (const [specifier] of Object.entries(ZONE_JS_SPECIFIER_REPLACEMENTS))
211			if (source.includes(`import(`) && source.includes(specifier))
212				unhandled.push(
213					`${path} may reach ${specifier} through a dynamic import, which this capability does not rewrite`,
214				);
215		const ordered = [...edits].sort((left, right) => right.start - left.start);
216		let migrated = source;
217		for (const edit of ordered)
218			migrated = `${migrated.slice(0, edit.start)}${edit.text}${migrated.slice(edit.end)}`;
219		const changes = [...edits]
220			.sort((left, right) => left.start - right.start)
221			.map((edit) => edit.change);
222		return Object.freeze({
223			path,
224			source: migrated,
225			changed: migrated !== source,
226			changes: Object.freeze(changes),
227			unhandled: Object.freeze([...new Set(unhandled)].sort(compareStrings)),
228		});
229	}
